<script setup lang="ts">
const db=useDb(),w=useWorkspace(),{error,busy,run}=useAction()
const form=reactive({title:'',customer_id:'',source:'email',original_text:'',received_date:new Date().toLocaleDateString('en-CA'),delivery_date:'',notes:''})
const {data:customers}=await useAsyncData('customer-options',async()=>check(await db.from('quolyn_customers').select('id,name').eq('workspace_id',w.value!.id)))
async function save(){await run(async()=>{const e=check(await db.from('quolyn_enquiries').insert({...form,workspace_id:w.value!.id,customer_id:form.customer_id||null,delivery_date:form.delivery_date||null}).select().single());await navigateTo('/enquiries/'+e.id)})}
</script>
<template><div><div class="page-title"><div><div class="eyebrow">ENQUIRIES / NEW</div><h1>Start with the customer’s words.</h1><p>Paste the original request. Keep the detail; resolve it together.</p></div></div><form class="panel" @submit.prevent="save"><div class="form-grid"><label>Enquiry title<input v-model="form.title" required maxlength="200" placeholder="e.g. Flooring for Oakline retail project"></label><label>Customer<select v-model="form.customer_id"><option value="">Assign later</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Source<select v-model="form.source"><option v-for="s in ['email','WhatsApp','phone','walk-in','other']" :key="s">{{s}}</option></select></label><label>Received date<input v-model="form.received_date" type="date" required></label></div><label>Original enquiry<textarea v-model="form.original_text" required maxlength="16000" rows="10" placeholder="Paste the customer’s message here…"></textarea></label><div class="form-grid"><label>Confirmed delivery date (optional)<input v-model="form.delivery_date" type="date"></label><label>Internal note<input v-model="form.notes"></label></div><p v-if="error" class="alert error" role="alert">{{error}}</p><div class="row between"><span class="muted">Nothing is sent to the customer.</span><button class="primary" :disabled="busy">Create enquiry →</button></div></form></div></template>
